/// Returns the host override from TESTCONTAINERS_HOST_OVERRIDE or TC_HOST
/// if set, otherwise falls back to the container's reported host.
/// This mirrors the behavior of testcontainers-java and testcontainers-go.
fn resolve_host(container: &testcontainers::Container<GenericImage>) -> String {
    std::env::var("TESTCONTAINERS_HOST_OVERRIDE")
        .or_else(|_| std::env::var("TC_HOST"))
        .unwrap_or_else(|_| {
            container
                .get_host()
                .expect("failed to get host")
                .to_string()
        })
}

/// Returns a mapped host port, retrying until Docker reports it.
///
/// `start()` returns once the container is running, but Docker publishes the
/// port mapping a moment later. Under load that gap widens, and the first read
/// fails with `PortNotExposed` — which failed roughly one run in two here,
/// taking a different test with it each time. Squid has no startup log line to
/// wait on, so a fixed three-second sleep stood in for readiness and lost the
/// race whenever the daemon was busy.
fn port_when_mapped(
    container: &testcontainers::Container<GenericImage>,
    port: u16,
    label: &str,
) -> u16 {
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(60);
    loop {
        match container.get_host_port_ipv4(port) {
            Ok(mapped) => return mapped,
            Err(err) => {
                if std::time::Instant::now() >= deadline {
                    panic!("failed to get {label} port {port} within 60s: {err}");
                }
                std::thread::sleep(std::time::Duration::from_millis(250));
            }
        }
    }
}

/// Serializes fixture-container creation across test binaries.
///
/// Cargo compiles each file under tests/ as its own binary and the runner
/// executes them concurrently, so they all reach the reuse check at the same
/// moment, all find nothing running, and all create their own pair. Reuse only
/// helps once a container exists, so the first one through has to finish before
/// the rest look. Holding a lock file for the creation window is enough: the
/// winner creates the pair, everyone else then finds and attaches to it.
fn with_creation_lock<T>(body: impl FnOnce() -> T) -> T {
    let lock_path = std::env::temp_dir().join("openapi-generator-fixture-containers.lock");
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(300);
    loop {
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(_) => break,
            Err(_) => {
                // A binary that died mid-creation would otherwise block every
                // later one for the whole run, so an old lock counts as free.
                let stale = std::fs::metadata(&lock_path)
                    .ok()
                    .and_then(|meta| meta.modified().ok())
                    .and_then(|modified| modified.elapsed().ok())
                    .is_some_and(|age| age > std::time::Duration::from_secs(240));
                if stale {
                    let _ = std::fs::remove_file(&lock_path);
                    continue;
                }
                // Proceed unlocked rather than fail the run outright: a
                // duplicate container is wasteful, a false failure is worse.
                if std::time::Instant::now() >= deadline {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(200));
            }
        }
    }
    let result = body();
    let _ = std::fs::remove_file(&lock_path);
    result
}

/// Returns an empty, world-writable directory to copy over the Squid image's
/// `/var/log/squid`.
///
/// A tmpfs mount inherits the mode of the directory it covers but is owned by
/// root, and `/var/log/squid` ships as `0755 proxy:proxy`, so a plain tmpfs
/// there is unwritable by the unprivileged `proxy` user Squid drops to and the
/// proxy dies opening `access.log`. `testcontainers`' `Mount` API cannot pass
/// tmpfs options, so the mode is widened on the image's own directory instead:
/// `with_copy_to` extracts its tar between container create and start, which
/// chmods the directory before the tmpfs is mounted over it.
fn writable_log_dir() -> PathBuf {
    let dir = std::env::temp_dir().join("openapi-generator-squid-log");
    std::fs::create_dir_all(&dir).expect("Failed to create the Squid log directory");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o1777))
            .expect("Failed to widen the Squid log directory");
    }
    dir
}

/// Fails the run when a dependency the generated tests import is missing from
/// `Cargo.toml`.
///
/// `.openapi-generator/DEV-DEPENDENCIES` is generator-owned; the manifest is
/// not, because it carries the package's own metadata and every real client
/// keep-lists it. Reading both here turns a drift between them into a message
/// naming the file instead of an opaque build failure.
fn check_dev_dependencies() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let listing = std::fs::read_to_string(root.join(".openapi-generator").join("DEV-DEPENDENCIES"))
        .expect("Failed to read .openapi-generator/DEV-DEPENDENCIES");
    let manifest =
        std::fs::read_to_string(root.join("Cargo.toml")).expect("Failed to read Cargo.toml");
    for line in listing.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let name = line.split_whitespace().next().unwrap_or_default();
        assert!(
            manifest.contains(name),
            "{name} is required by the generated tests but is not declared in Cargo.toml; \
             every entry in .openapi-generator/DEV-DEPENDENCIES must be declared there"
        );
    }
}

fn init_containers_inner() -> TestContainers {
    check_dev_dependencies();
    with_creation_lock(|| {
        let fixtures = fixtures_dir();
        let squid_conf_path = fixtures.join("proxy").join("squid.conf");
        let spec_path = fixtures.join("openapi.yaml");
        let ca_cert = fixtures.join("certs").join("ca.pem");

        // Start Squid
        let squid_log_dir = writable_log_dir();
        let squid = GenericImage::new("ubuntu/squid", "5.2-22.04_beta")
            .with_exposed_port(ContainerPort::Tcp(3128))
            .with_exposed_port(ContainerPort::Tcp(3129))
            .with_label("io.openapi-generator.fixture", "squid")
            .with_reuse(ReuseDirective::Always)
            .with_copy_to("/etc/squid/squid.conf", squid_conf_path)
            // See writable_log_dir: widens /var/log/squid before the tmpfs
            // below is mounted over it.
            .with_copy_to("/var/log/squid", squid_log_dir)
            // ubuntu/squid declares VOLUME /var/log/squid and
            // /var/spool/squid, so every proxy container would otherwise
            // leave two anonymous volumes behind. tmpfs mounts satisfy the
            // VOLUME declarations without any volume being created.
            .with_mount(Mount::tmpfs_mount("/var/log/squid"))
            .with_mount(Mount::tmpfs_mount("/var/spool/squid"))
            .with_startup_timeout(std::time::Duration::from_secs(120))
            .start()
            .expect("Failed to start Squid container");

        let squid_host = resolve_host(&squid);
        let squid_port = port_when_mapped(&squid, 3128, "Squid");
        // 3129 is the same proxy but answers 407 unless the request carries
        // Proxy-Authorization credentials.
        let squid_auth_port = port_when_mapped(&squid, 3129, "Squid (auth)");

        // Start Chasm
        let chasm_cert_path = fixtures.join("certs").join("server.pem");
        let chasm_key_path = fixtures.join("certs").join("server-key.pem");
        let chasm = GenericImage::new("mridang/chasm", "1.3.0")
            .with_exposed_port(ContainerPort::Tcp(4010))
            .with_exposed_port(ContainerPort::Tcp(8443))
            .with_wait_for(WaitFor::message_on_stdout("Listening on"))
            .with_label("io.openapi-generator.fixture", "chasm")
            .with_reuse(ReuseDirective::Always)
            .with_copy_to("/tmp/openapi.yaml", spec_path)
            .with_copy_to("/certs/cert.pem", chasm_cert_path)
            .with_copy_to("/certs/key.pem", chasm_key_path)
            .with_cmd(vec![
                "mock".to_string(),
                "/tmp/openapi.yaml".to_string(),
                "--host".to_string(),
                "0.0.0.0".to_string(),
                "--tls-cert".to_string(),
                "/certs/cert.pem".to_string(),
                "--tls-key".to_string(),
                "/certs/key.pem".to_string(),
                "--tls-port".to_string(),
                "8443".to_string(),
            ])
            .with_startup_timeout(std::time::Duration::from_secs(120))
            .start()
            .expect("Failed to start Chasm container");

        let chasm_host = resolve_host(&chasm);
        let chasm_bridge_ip = chasm
            .get_bridge_ip_address()
            .expect("failed to get Chasm bridge IP");
        let chasm_port = port_when_mapped(&chasm, 4010, "Chasm");
        let chasm_https_port = port_when_mapped(&chasm, 8443, "Chasm HTTPS");

        // Keep the containers alive for the lifetime of this test binary: the
        // handles are locals, and dropping them would remove the very
        // containers the tests are about to talk to — and, now that they are
        // shared, the ones every other test binary is using too.
        //
        // Cargo compiles each file under tests/ as its own binary, so this
        // function runs once per binary rather than once per run. Each used to
        // start its own Squid and Chasm and then strand them, leaving fifty-odd
        // containers behind and starving the daemon partway through the run,
        // which surfaced as unrelated tests failing to reach a port. The
        // reuse directive above makes the first binary create the pair and
        // every later one attach to it, matched on the fixture label, so a
        // whole run now leaves exactly two.
        std::mem::forget(squid);
        std::mem::forget(chasm);

        TestContainers {
            proxy_url: format!("http://{}:{}", squid_host, squid_port),
            auth_proxy_url: format!("http://{}:{}", squid_host, squid_auth_port),
            chasm_url: format!("http://{}:{}", chasm_host, chasm_port),
            chasm_http_url: format!("http://{}:{}", chasm_host, chasm_port),
            chasm_https_url: format!("https://{}:{}", chasm_host, chasm_https_port),
            chasm_internal_http_url: format!("http://{}:4010", chasm_bridge_ip),
            chasm_internal_https_url: format!("https://{}:8443", chasm_bridge_ip),
            ca_cert_path: ca_cert.to_str().unwrap().to_string(),
        }
    })
}

